static void *fake_window = (void *)0x2000;
static void *fake_box = (void *)0x3000;
static void *fake_textview = (void *)0x4000;
static void *fake_buffer = (void *)0x5000;
static void *fake_tag = (void *)0x6000;

static gpointer activate_cb = NULL;
static gpointer changed_cb = NULL;

#define TYPE(n) ((void *)(0x7000 + (n)))

/* ---- fake type tokens ---- */
void *g_application_get_type(void) { fprintf(stderr, "[stub] g_application_get_type\n"); return TYPE(1); }
void *gtk_window_get_type(void)    { return TYPE(2); }
void *gtk_box_get_type(void)       { return TYPE(3); }
void *gtk_text_view_get_type(void) { return TYPE(4); }

void *g_type_check_instance_cast(void *instance, void *type) {
    (void)type;
    return instance;
}

/* ---- application ---- */
void *gtk_application_new(const char *app_id, int flags) {
    (void)flags;
    fprintf(stderr, "[stub] gtk_application_new(app_id=\"%s\")\n", app_id ? app_id : "(null)");
