    (void)instance; (void)data; (void)destroy; (void)flags;
    fprintf(stderr, "[stub] g_signal_connect_data(signal=\"%s\", cb=%p)\n", signal ? signal : "(null)", cb);
    if (signal && strcmp(signal, "activate") == 0) activate_cb = cb;
    if (signal && strcmp(signal, "changed") == 0) changed_cb = cb;
    return 1;
}

/* returns 0 => program prints nothing else; stub drives callbacks itself */
